import React, { forwardRef, useEffect, useImperativeHandle, useRef, useState } from 'react'
import { View } from 'react-native'
import { WebView } from 'react-native-webview'
import { File } from 'expo-file-system'
import { useLibrary } from '../stores/useLibrary'
import { useTheme } from '../stores/useTheme'
import { sandTable, type SandTable } from '../lib/tableSize'
import { prepareSand } from '../lib/sandFiles'
// @ts-ignore - generated by scripts/gen-sand.mjs (plain JS)
import { KEY } from '../../assets/sand'

// The Sand Weaver sand engine (dune-weaver-viewer's Sand page, vendored by
// `npm run gen-sand`) simulating a pattern as the table draws it, on the table's
// own clear: Browse's preview player shows it on round tables. It runs in a
// WebView (WebGL2) loaded from a cache folder holding the page and the table's
// clear, the one folder the page may read (file:// pages can't read bundled assets).

/** Whether the sand engine runs here (desktop too: SandView.web.tsx). */
export const SAND = true

export { sandTable, type SandTable }

export interface SandState {
  /** Share of the pattern simulated and shown, 0..1. */
  f: number
  playing: boolean
  /** loading = the page isn't up; the rest are the engine's: running the clear, catching up, or keeping pace. */
  phase: 'loading' | 'clearing' | 'simulating' | 'ready'
}

export interface SandHandle {
  play(): void
  pause(): void
  /** To a share of the pattern, 0..1. */
  seek(f: number): void
  speed(x: number): void
}

/** The engine's key: it changes with the page, the engine, the clears or a ball. */
export const SAND_KEY = KEY as string

interface Props {
  /** A pattern the app holds (bundled or imported). */
  name: string
  /** Its .thr text instead, for a pattern not saved yet (Create's sand preview). */
  thr?: string
  table: SandTable
  size: number
  onState?: (s: SandState) => void
  /**
   * Render a STILL instead of playing (the sand preview worker): the finished sand
   * at `still` px, handed to onStill as a data URL (PNG: WebKit can't encode WebP).
   */
  still?: number
  onStill?: (dataUrl: string) => void
  /** The engine can't run here (no WebGL2 float targets) or the page died: fall back. */
  onError: (message: string) => void
}

export const SandView = forwardRef<SandHandle, Props>(function SandView({ name, thr: given, table, size, onState, still, onStill, onError }, ref) {
  const { sandLight, sandLift, sandLiftBlend } = useTheme((s) => s.colors)
  // WebView<object>: its default props type, WebViewProps & undefined, is never under this TS.
  const web = useRef<WebView<object>>(null)
  const [setup, setSetup] = useState<{ dir: string; thr: string } | null>(null)
  // Commands sent before the page is up wait for it (Browse's autoplay comes first).
  const ready = useRef(false)
  const queued = useRef<string[]>([])
  const send = (js: string) => {
    if (ready.current) web.current?.injectJavaScript(`${js};true;`)
    else queued.current.push(js)
  }
  useImperativeHandle(ref, () => ({
    play: () => send('sandPlayer.play()'),
    pause: () => send('sandPlayer.pause()'),
    seek: (f: number) => send(`sandPlayer.seek(${f})`),
    speed: (x: number) => send(`sandPlayer.speed(${x})`),
  }))

  useEffect(() => {
    let live = true
    ;(async () => {
      let thr = given
      if (thr == null) {
        const local = await useLibrary.getState().resolveThr(name)
        if (!local) throw new Error('This pattern isn’t on the phone.')
        thr = await new File(local.uri).text()
      }
      const dir = await prepareSand(table)
      if (live) setSetup({ dir, thr })
    })().catch((e: unknown) => live && onError(e instanceof Error ? e.message : String(e)))
    return () => {
      live = false
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- once per pattern and table
  }, [name, given, table])

  if (!setup) return <View style={{ width: size, height: size }} />
  return (
    <WebView<object>
      ref={web}
      source={{ uri: `${setup.dir}index.html` }}
      allowingReadAccessToURL={setup.dir}
      allowFileAccess
      allowFileAccessFromFileURLs
      originWhitelist={['*']}
      injectedJavaScriptBeforeContentLoaded={`window.SAND=${JSON.stringify({ thr: setup.thr, table, size, ...(still ? { still: { size: still } } : {}) })};true;`}
      // The table's light (theme sandLight), multiplied over the sand and the ball, as on
      // the thumbnails. Injected rather than in the page: the page is the engine's KEY,
      // and a change there would re-render every hub preview. A still reads the canvas, so it stays neutral.
      injectedJavaScript={`(()=>{for(const [c,m] of ${JSON.stringify([[sandLight, 'multiply'], ...(sandLift ? [[sandLift, sandLiftBlend]] : [])])}){const d=document.createElement('div');d.style.cssText='position:absolute;inset:0;border-radius:50%;pointer-events:none;mix-blend-mode:'+m+';background:'+c;document.body.appendChild(d)}})();true;`}
      onMessage={(e) => {
        const m = JSON.parse(e.nativeEvent.data) as { t: 'ready' } | { t: 'error'; message: string } | { t: 'still'; data: string } | ({ t: 'state' } & SandState)
        if (m.t === 'ready') {
          ready.current = true
          for (const js of queued.current.splice(0)) web.current?.injectJavaScript(`${js};true;`)
        } else if (m.t === 'error') onError(m.message)
        else if (m.t === 'still') onStill?.(m.data)
        else onState?.({ f: m.f, playing: m.playing, phase: m.phase })
      }}
      onError={(e) => onError(`The sand preview didn’t load: ${e.nativeEvent.description}`)}
      onContentProcessDidTerminate={() => onError('The sand preview stopped.')}
      onRenderProcessGone={() => onError('The sand preview stopped.')}
      scrollEnabled={false}
      bounces={false}
      overScrollMode="never"
      showsHorizontalScrollIndicator={false}
      showsVerticalScrollIndicator={false}
      style={{ width: size, height: size, backgroundColor: 'transparent' }}
      containerStyle={{ flex: 0, width: size, height: size }}
    />
  )
})
